// Shared ledger vectors (tests/economy/vectors.json, generated by the star-pets tooling against sync.md §8.4) validated against kit/sync/ledger.ts.
// Same data, same assertions as ~/kid-games-work/specs/pets-tools/vectors-check.mjs; the star-pets-only sections (growth / room / slotOrder) belong to kit/economy (S8) and are checked for shape only.
import { describe, expect, it } from 'vitest';
import * as L from '@kit/sync/ledger';
import V from './vectors.json';

// natural-event table used by the vectors: every canonical natural vector defines its own entry (id -> kind/amount/src/ref); rejected vectors are measured against it.
const TABLE: L.NaturalTable = Object.fromEntries((V.natural.canonical as L.LedgerEvent[]).map((e) => [e.id, { kind: e.kind, amount: e.amount, src: e.src, ref: e.ref }]));
const asEv = (x: unknown): L.LedgerEvent => x as L.LedgerEvent;

describe('vectors: meta + id contract', () => {
  it('the contract constants equal the vector meta', () => {
    expect(L.ID_RE.source).toBe(V.meta.ID_RE);
    expect(L.DEV_RE.source).toBe(V.meta.DEV_RE);
    expect(L.NATURAL_RE.source).toBe(V.meta.NATURAL_RE);
    expect(L.MAX_AMOUNT).toBe(V.meta.MAX_AMOUNT);
    expect(V.meta.order).toContain('(lc,d,id)');
  });
  it.each(V.ids.valid)('valid id %s', (id) => { expect(new RegExp(V.meta.ID_RE).test(id)).toBe(true); expect(L.ID_RE.test(id)).toBe(true); });
  it.each(V.ids.invalid)('invalid id %j', (id) => { expect(L.ID_RE.test(id)).toBe(false); });
  it.each(V.lcSeed)('lcSeed($nowMs) = $seed', (c) => { expect(L.lcSeed(c.nowMs)).toBe(c.seed); });
});
describe('vectors: natural (canonical) events', () => {
  it.each(V.natural.canonical.map((e) => [e.id, e] as const))('canonical %s is valid and matches its table row', (_id, e) => { expect(L.validEv(e)).toBe(true); expect(L.validNatural(asEv(e), TABLE)).toBe(true); });
  it.each(V.natural.rejected.map((r) => [r.why, r.ev] as const))('rejected: %s', (_why, ev) => { expect(L.validEv(ev) && L.validNatural(asEv(ev), TABLE)).toBe(false); });
});
describe('vectors: fold, union, safe point', () => {
  it.each(V.fold.map((c) => [c.name, c] as const))('fold: %s', (_n, c) => {
    const shuffled = [...c.events].reverse();
    const b = L.balance(shuffled.map(asEv));
    expect(b.balance).toBe(c.expect.balance);
    expect(b.forgiven).toBe(c.expect.forgiven);
    expect([...shuffled].map(asEv).sort(L.cmpEv).map((e) => e.id)).toEqual(c.expect.order);
    expect(L.rawSum(shuffled.map(asEv))).toBe(c.expect.rawSum);
  });
  it.each(V.union.map((c) => [c.name, c] as const))('union: %s', (_n, c) => {
    const key = (xs: L.LedgerEvent[]) => xs.map((e) => [e.id, e.d, e.lc]);
    expect(key(L.unionLedger(c.a, c.b))).toEqual(c.expect);
    expect(key(L.unionLedger(c.b, c.a))).toEqual(c.expect);
  });
  it.each(V.safePoint.map((c) => [c.name, c] as const))('safe point: %s', (_n, c) => {
    const pre = L.balance(c.shown as L.LedgerEvent[]).balance, post = L.balance(L.unionLedger(c.shown, c.batch)).balance;
    expect(pre).toBe(c.expect.before);
    expect(post).toBe(c.expect.after);
    expect(pre - post).toBeLessThanOrEqual(c.expect.maxDrop);
  });
});
describe('vectors: star-pets-only sections (kit/economy, S8)', () => {
  it('growth, room and slotOrder are present and well-formed', () => {
    expect(V.growth.length).toBeGreaterThan(0);
    expect(V.room.length).toBeGreaterThan(0);
    expect(V.slotOrder.length).toBe(15);
    expect(new Set(V.slotOrder).size).toBe(15);
  });
});
